
const $=id=>document.getElementById(id);
const initial={"date":"Zaterdag · 1 Juli","time":"12:07","location":"Slaapkamer","concept":true,"scenes":[[{"sender":"Maaike me liefste","text":"Joel… ben je al wakker?"},{"sender":"Geert","text":"Weet je nog iets van gisteren?"},{"sender":"Geert","text":"Foto"}],[{"sender":"Naam afzender","text":"Hier komt het eerste appje van scène 2."},{"sender":"","text":""},{"sender":"","text":""}],[{"sender":"Naam afzender","text":"Hier komt het eerste appje van scène 3."},{"sender":"","text":""},{"sender":"","text":""}],[{"sender":"Naam afzender","text":"Hier komt het eerste appje van scène 4."},{"sender":"","text":""},{"sender":"","text":""}],[{"sender":"Naam afzender","text":"Hier komt het eerste appje van scène 5."},{"sender":"","text":""},{"sender":"","text":""}]]};
initial.photos=Array.from({length:5},()=>[]);initial.wallpaper=null;initial.wallpaperShade=.3;
let photoIndex=-1, photoLoad=0, importingPhotos=false;
let config=structuredClone(initial), scene=0, shown=0, playing=false,start=0,raf=0,lastEvent=-1,audioCtx;
const icon='<span class="wa"><svg viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="1.8"><path d="M20 11.5a8.5 8.5 0 0 1-12.7 7.4L3 20l1.2-4.2A8.5 8.5 0 1 1 20 11.5Z"/><path d="M8 7c0 5 3 8 8 8l1-2-3-1-1 1c-2-1-3-2-3-4l1-1-2-2Z"/></svg></span>';
function fit(){const v=$('viewport');const scale=Math.min(v.clientWidth/1920,v.clientHeight/1080);$('stage').style.transform='scale('+scale+')';$('stage').style.left=(v.clientWidth-1920*scale)/2+'px';$('stage').style.top=(v.clientHeight-1080*scale)/2+'px'}
new ResizeObserver(fit).observe($('viewport'));
function messages(){return config.scenes[scene].filter(m=>m.text.trim()||m.photo)}
function base(){ $('date').textContent=config.date;$('time').textContent=config.time;$('location').textContent=config.location;$('concept').hidden=!config.concept;applyWallpaper(); }
function card(m,progress=1){const el=document.createElement('div');el.className='notice';el.innerHTML='<div class="meta">'+icon+'<span>WHATSAPP</span><span class="age">nu</span></div><div class="notice-content"><div class="notice-copy"><div class="sender"></div><div class="message"></div></div></div>';el.querySelector('.sender').textContent=m.sender||'Onbekend';el.querySelector('.message').textContent=m.text;el.querySelector('.message').hidden=!m.text.trim();if(m.photo){el.classList.add('has-photo');const img=document.createElement('img');img.className='message-photo';img.alt=m.photo.name;img.src=m.photo.src;el.querySelector('.notice-content').append(img)}const p=1-Math.pow(1-Math.min(1,Math.max(0,progress)),3);el.style.opacity=p;el.style.transform='translateY('+(-28*(1-p))+'px) scale('+(0.97+.03*p)+')';return el}
function fitCards(){const n=$('notifications');n.style.transformOrigin='top center';n.style.transform='scale('+Math.min(1,525/n.scrollHeight)+')'}
function show(count,animation=false){hidePhoto();base();$('alarm').hidden=true;$('notifications').replaceChildren(...messages().slice(0,count).map(m=>card(m)));fitCards();if(animation&&count){$('notifications').lastElementChild?.animate([{opacity:0,transform:'translateY(-28px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:350,easing:'ease-out'});} $('state').textContent='Scène '+(scene+1)+' · '+count+' van '+messages().length+' appjes zichtbaar';updateControls();}
function audio(){if(!$('soundInput').checked)return null;audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();return audioCtx}
function tone(type){if(type==='alarm'){if($('soundInput').checked)playRadar();return}const c=audio();if(!c)return;const notes=[[880,0,.11],[1320,.12,.18]];for(const [f,d,l]of notes){const o=c.createOscillator(),g=c.createGain(),t=c.currentTime+d;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.12,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+l);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+l+.02)}}
function stop(){playing=false;cancelAnimationFrame(raf);stopRadar()}
function next(){stop();if(photoIndex>=0){if(photoIndex+1<photos().length)showPhoto(photoIndex+1);else phone();return}if(shown<messages().length){shown++;show(shown,true);tone('notice')}else if(photos().length)showPhoto(0)}
function previous(){stop();if(photoIndex>0)showPhoto(photoIndex-1);else if(photoIndex===0)phone();else{shown=Math.max(0,shown-1);show(shown)}}
function reset(){stop();shown=0;show(0)}
function clockAfter(minutes){const [h,m]=config.time.split(':').map(Number);let v=(h*60+m+minutes)%1440;return String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0')}
window.renderAt=function(t){hidePhoto();base();$('time').textContent=clockAfter(t<2.5?0:t<5?9:18);$('alarm').hidden=t>=6;const starts=[7,12,17];$('notifications').replaceChildren(...messages().filter((m,i)=>t>=starts[i]).map((m,i)=>card(m,(t-starts[i])/.38)));fitCards();};
function tick(now){const t=(now-start)/1000;renderAt(t);const events=[0,2.5,5,7,12,17];for(let i=lastEvent+1;i<events.length;i++){if(t>=events[i]){if(i<3||messages()[i-3])tone(i<3?'alarm':'notice');lastEvent=i;}}if(t>=6)stopRadar();if(t<24&&playing)raf=requestAnimationFrame(tick);else{playing=false;shown=messages().length;$('state').textContent='Demo afgelopen. Klik op Toon foto’s voor de beelden bij deze scène.';updateControls()}}
function bind(){base();$('shadeInput').value=config.wallpaperShade??.3;syncWallpaperPanel();$('dateInput').value=config.date;$('timeInput').value=config.time;$('locInput').value=config.location;$('conceptInput').checked=config.concept;$('sceneInput').value=scene;$('messageFields').replaceChildren();config.scenes[scene].forEach((m,i)=>{const label=document.createElement('label');label.textContent='Appje '+(i+1)+' · afzender';const name=document.createElement('input');name.maxLength=35;name.value=m.sender;name.setAttribute('aria-label','Afzender appje '+(i+1));const txt=document.createElement('textarea');txt.maxLength=110;txt.value=m.text;txt.setAttribute('aria-label','Tekst appje '+(i+1));name.oninput=()=>{m.sender=name.value;reset()};txt.oninput=()=>{m.text=txt.value;reset()};$('messageFields').append(label,name,txt,attachmentEditor(m,i));});renderPhotos();reset()}
for(const [id,key]of [['dateInput','date'],['timeInput','time'],['locInput','location']])$(id).oninput=()=>{config[key]=$(id).value||initial[key];reset()};
$('conceptInput').onchange=()=>{config.concept=$('conceptInput').checked;base()};$('sceneInput').onchange=()=>{scene=Number($('sceneInput').value);bind()};
$('next').onclick=next;$('back').onclick=previous;$('reset').onclick=reset;$('demo').onclick=()=>{stop();audio();playing=true;start=performance.now();lastEvent=-1;raf=requestAnimationFrame(tick)};
$('full').onclick=async()=>{try{await $('viewport').requestFullscreen();document.activeElement.blur()}catch{$('error').textContent='Volledig scherm is hier niet beschikbaar. Open dit HTML-bestand in Chrome of Edge.'}};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||(document.activeElement.tagName==='BUTTON'&&document.activeElement.closest('.panel')))return;if(e.code==='Space'||e.key==='ArrowRight'){e.preventDefault();next()}else if(e.key==='ArrowLeft'){$('back').click()}else if(e.key.toLowerCase()==='f'){if(photos().length)showPhoto(0)}else if(e.key.toLowerCase()==='t')phone();else if(e.key.toLowerCase()==='r')reset();else if(/^[1-5]$/.test(e.key)){scene=Number(e.key)-1;bind()}else if(e.key==='Escape'){stop();if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})}});
$('save').onclick=()=>{if(importingPhotos)return;const url=URL.createObjectURL(new Blob([JSON.stringify(config,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='Joel-project.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('load').onclick=()=>$('fileInput').click();$('fileInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const c=JSON.parse(await file.text());if(typeof c.date!=='string'||typeof c.location!=='string'||!/^([01]\d|2[0-3]):[0-5]\d$/.test(c.time)||!Array.isArray(c.scenes)||c.scenes.length!==5||c.scenes.some(s=>!Array.isArray(s)||s.length!==3||s.some(m=>typeof m.sender!=='string'||m.sender.length>35||typeof m.text!=='string'||m.text.length>110))||c.date.length>45||c.location.length>35)throw Error();config=normalizeConfig(c);scene=0;bind();$('error').textContent='';}catch{$('error').textContent='Dit bestand heeft niet het juiste formaat. Kies een eerder bewaard Joel-project.json of Joel-teksten.json bestand.'}e.target.value=''};

function normalizeConfig(c){
  const result=structuredClone(c);
  if(result.photos===undefined)result.photos=Array.from({length:5},()=>[]);
  if(!Array.isArray(result.photos)||result.photos.length!==5||result.photos.some(list=>!Array.isArray(list)||list.length>20||list.some(p=>!p||typeof p.name!=='string'||typeof p.src!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+=*$/.test(p.src))))throw Error('Ongeldige foto’s');
  if(result.wallpaper===undefined)result.wallpaper=null;
  if(result.wallpaper&&!validImage(result.wallpaper))throw Error('Ongeldige achtergrond');
  if(result.scenes.some(list=>list.some(m=>m.photo&&!validImage(m.photo))))throw Error('Ongeldige appfoto');
  result.wallpaperShade=Number.isFinite(result.wallpaperShade)?Math.min(.7,Math.max(0,result.wallpaperShade)):.3;
  return result;
}
function photos(){return config.photos[scene]}
function hidePhoto(){photoLoad++;photoIndex=-1;$('photoScreen').hidden=true;$('photoDisplay').removeAttribute('src');}
function updateControls(){
  const viewing=photoIndex>=0;
  $('photosButton').disabled=!photos().length;
  $('phoneButton').hidden=!viewing;
  $('next').disabled=!viewing&&shown>=messages().length&&!photos().length;
  $('next').textContent=viewing?(photoIndex+1<photos().length?'Volgende foto →':'Terug naar telefoon →'):(shown<messages().length?'Volgend appje →':photos().length?'Toon foto’s →':'Alle appjes getoond');
}
async function showPhoto(index){
  if(!photos()[index])return;
  stop();const token=++photoLoad;const photo=photos()[index];
  const img=new Image();img.src=photo.src;
  try{await img.decode()}catch{if(token===photoLoad)$('error').textContent='Deze foto kan niet worden getoond. Voeg hem opnieuw toe als JPG of PNG.';return}
  if(token!==photoLoad)return;
  photoIndex=index;$('photoDisplay').src=photo.src;$('photoDisplay').alt=photo.name;$('photoScreen').hidden=false;
  $('state').textContent='Scène '+(scene+1)+' · foto '+(index+1)+' van '+photos().length+' · '+photo.name;
  updateControls();
}
function phone(){stop();show(shown)}
function renderPhotos(){
  const list=$('photoList');list.replaceChildren();
  if(!photos().length){const empty=document.createElement('div');empty.className='photo-empty';empty.textContent='Nog geen foto’s. Voeg de beelden voor deze herinnering toe.';list.append(empty)}
  photos().forEach((p,i)=>{
    const row=document.createElement('div');row.className='photo-row';
    const thumb=document.createElement('button');thumb.className='photo-thumb';thumb.title='Toon foto '+(i+1);thumb.setAttribute('aria-label',thumb.title);
    const img=document.createElement('img');img.src=p.src;img.alt=p.name;thumb.append(img);thumb.onclick=()=>showPhoto(i);
    const info=document.createElement('div');info.style.minWidth='0';const name=document.createElement('div');name.className='photo-name';name.textContent=(i+1)+'. '+p.name;name.title=p.name;
    const actions=document.createElement('div');actions.className='photo-actions';
    function action(label,title,disabled,fn){const b=document.createElement('button');b.textContent=label;b.title=title;b.setAttribute('aria-label',title);b.disabled=disabled;b.onclick=()=>{phone();fn();renderPhotos();updateControls()};actions.append(b)}
    action('↑','Foto '+(i+1)+' naar voren',i===0,()=>{[photos()[i-1],photos()[i]]=[photos()[i],photos()[i-1]]});
    action('↓','Foto '+(i+1)+' naar achteren',i===photos().length-1,()=>{[photos()[i+1],photos()[i]]=[photos()[i],photos()[i+1]]});
    action('Verwijder','Verwijder foto '+(i+1),false,()=>photos().splice(i,1));
    info.append(name,actions);row.append(thumb,info);list.append(row);
  });updateControls();
}
async function readPhoto(file){
  if(!/\.(jpe?g|png|webp)$/i.test(file.name)&&!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error(file.name+': gebruik JPG, PNG of WebP.');
  if(file.size>30*1024*1024)throw Error(file.name+': dit bestand is groter dan 30 MB.');
  const url=URL.createObjectURL(file);const img=new Image();
  try{
    img.src=url;await img.decode();const scale=Math.min(1,2560/Math.max(img.naturalWidth,img.naturalHeight));
    const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));
    const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
    return{name:file.name,src:canvas.toDataURL('image/jpeg',.91)};
  }catch{throw Error(file.name+': kon niet worden geopend. Exporteer de foto als JPG of PNG.')}finally{URL.revokeObjectURL(url)}
}
$('addPhotos').onclick=()=>$('photoInput').click();
$('photoInput').onchange=async e=>{
  const files=Array.from(e.target.files);e.target.value='';if(!files.length)return;
  const targetScene=scene,target=photos();const room=20-target.length;const chosen=files.slice(0,room);const errors=[];let added=0;
  if(files.length>room)errors.push('Maximaal 20 foto’s per scène; de overige bestanden zijn overgeslagen.');
  importingPhotos=true;$('addPhotos').disabled=true;$('save').disabled=true;$('load').disabled=true;$('error').textContent='';
  try{for(const [i,file]of chosen.entries()){$('photoStatus').textContent='Foto '+(i+1)+' van '+chosen.length+' verwerken voor scène '+(targetScene+1)+'…';try{target.push(await readPhoto(file));added++}catch(err){errors.push(err.message)}}}
  finally{importingPhotos=false;$('addPhotos').disabled=false;$('save').disabled=false;$('load').disabled=false;renderPhotos();$('photoStatus').textContent=added+' foto’s toegevoegd aan scène '+(targetScene+1)+'. Bewaar je project om ze te bewaren.';$('error').textContent=errors.join(' ')}
};
$('photosButton').onclick=()=>showPhoto(0);$('phoneButton').onclick=phone;


const radar=new Audio('data:audio/mp4;base64,');radar.preload='auto';radar.volume=.75;
function stopRadar(){radar.pause();radar.currentTime=0;$('testRadar').textContent='Beluister Radar'}
function playRadar(){stopRadar();$('testRadar').textContent='Stop Radar';radar.play().catch(()=>{$('testRadar').textContent='Beluister Radar';$('error').textContent='Het geluid kon niet starten. Klik opnieuw op Beluister Radar.'})}
radar.onended=()=>{$('testRadar').textContent='Beluister Radar'};
$('testRadar').onclick=()=>{if(!radar.paused){stopRadar()}else{stop();playRadar()}};
$('soundInput').onchange=()=>{if(!$('soundInput').checked)stopRadar()};
function validImage(p){return p&&typeof p.name==='string'&&typeof p.src==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+=*$/.test(p.src)}
function applyWallpaper(){const wp=config.wallpaper;$('stage').classList.toggle('has-wallpaper',!!wp);$('wallpaper').hidden=!wp;if(wp){if($('wallpaperImage').getAttribute('src')!==wp.src)$('wallpaperImage').src=wp.src}else $('wallpaperImage').removeAttribute('src');$('wallpaperShade').style.opacity=config.wallpaperShade??.3}
function syncWallpaperPanel(){$('wallpaperStatus').textContent=config.wallpaper?'Achtergrond: '+config.wallpaper.name:'De groene standaardachtergrond is actief.';$('clearWallpaper').hidden=!config.wallpaper;$('shadeInput').disabled=!config.wallpaper}
$('chooseWallpaper').onclick=()=>$('wallpaperInput').click();
$('wallpaperInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;const target=config;$('chooseWallpaper').disabled=true;$('error').textContent='';try{const p=await readPhoto(file);if(target===config){config.wallpaper=p;applyWallpaper();syncWallpaperPanel()}}catch(err){$('error').textContent=err.message}finally{$('chooseWallpaper').disabled=false}};
$('clearWallpaper').onclick=()=>{config.wallpaper=null;applyWallpaper();syncWallpaperPanel()};
$('shadeInput').oninput=()=>{config.wallpaperShade=Number($('shadeInput').value);applyWallpaper()};
function attachmentEditor(m,i){
 const box=document.createElement('div');box.className='attachment-editor';
 const file=document.createElement('input');file.type='file';file.accept='image/jpeg,image/png,image/webp';file.hidden=true;file.dataset.messagePhoto=i;
 const add=document.createElement('button');add.textContent=m.photo?'Foto vervangen':'Foto in appje laden';add.setAttribute('aria-label','Foto laden in appje '+(i+1));add.onclick=()=>file.click();
 box.append(add,file);
 if(m.photo){const img=document.createElement('img');img.src=m.photo.src;img.alt=m.photo.name;const name=document.createElement('span');name.className='attachment-name';name.textContent=m.photo.name;name.title=m.photo.name;const remove=document.createElement('button');remove.textContent='Foto verwijderen';remove.setAttribute('aria-label','Foto verwijderen uit appje '+(i+1));remove.onclick=()=>{delete m.photo;bind();shown=messages().length;show(shown)};box.append(img,name,remove)}
 file.onchange=async e=>{const chosen=e.target.files[0];file.value='';if(!chosen)return;const targetScene=scene;add.disabled=true;$('error').textContent='';try{const photo=await readPhoto(chosen);m.photo=photo;if(targetScene===scene&&config.scenes[scene].includes(m)){bind();shown=messages().length;show(shown)}}catch(err){$('error').textContent=err.message}finally{add.disabled=false}};
 return box;
}

if(new URLSearchParams(location.search).has('render'))document.body.classList.add('render');
window.setConfig=c=>{config=normalizeConfig(c);scene=0;bind()};window.getConfig=()=>config;bind();
